import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const radioGroup = tv({
  slots: {
    root: "flex",
    item: [
      "inline-flex w-fit cursor-pointer items-center gap-3 font-medium text-foreground",
      "has-data-disabled:cursor-not-allowed has-data-disabled:text-disabled-foreground",
    ],
    radio: [
      "relative inline-flex shrink-0 items-center justify-center rounded-lg",
      "border-3 border-border bg-raised",
      "after:absolute after:content-['']",
      "data-invalid:bg-danger/15",
      "data-disabled:border-disabled-foreground data-disabled:bg-disabled data-disabled:data-checked:bg-disabled",
      focusRing,
    ],
    indicator:
      "rounded-lg border-2 border-border bg-foreground data-disabled:bg-disabled-foreground",
  },
  variants: {
    variant: {
      primary: { radio: "data-checked:bg-primary" },
      secondary: { radio: "data-checked:bg-secondary" },
      danger: { radio: "data-checked:bg-danger" },
    },
    size: {
      sm: { radio: "size-5 border-2 after:-inset-3", indicator: "size-2", item: "text-sm" },
      md: { radio: "size-6 after:-inset-2.5", indicator: "size-2.5", item: "text-base" },
      lg: { radio: "size-8 after:-inset-1.5", indicator: "size-3.5", item: "text-lg" },
    },
    orientation: {
      vertical: { root: "flex-col gap-3" },
      horizontal: { root: "flex-row flex-wrap gap-x-6 gap-y-3" },
    },
  },
  defaultVariants: {
    variant: "primary",
    size: "md",
    orientation: "vertical",
  },
});

export type RadioGroupVariants = VariantProps<typeof radioGroup>;

"use client";

import { Radio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { radioGroup, type RadioGroupVariants } from "@/lib/beton/recipes/radio-group.recipe";
import { createContext, useContext, type ComponentProps, type ReactNode, type Ref } from "react";

type Context = Pick<RadioGroupVariants, "variant" | "size">;
const RadioGroupContext = createContext<Context>({ variant: "primary", size: "md" });

export interface RadioGroupProps
  extends Omit<BaseRadioGroup.Props, "className">, RadioGroupVariants {
  className?: string;
}

function RadioGroupRoot({
  variant = "primary",
  size = "md",
  orientation = "vertical",
  className,
  ...props
}: RadioGroupProps) {
  return (
    <RadioGroupContext.Provider value={{ variant, size }}>
      <BaseRadioGroup
        {...props}
        aria-orientation={orientation}
        data-orientation={orientation}
        data-size={size}
        className={radioGroup({ orientation }).root({ class: className })}
      />
    </RadioGroupContext.Provider>
  );
}

export interface RadioGroupItemProps extends Omit<ComponentProps<"label">, "children"> {
  /** The value submitted when this option is selected. */
  value: string;
  disabled?: boolean;
  readOnly?: boolean;
  inputRef?: Ref<HTMLInputElement>;
  children: ReactNode;
}

function RadioGroupItem({
  value,
  disabled,
  readOnly,
  inputRef,
  className,
  children,
  ...props
}: RadioGroupItemProps) {
  const { variant, size } = useContext(RadioGroupContext);
  const styles = radioGroup({ variant, size });
  return (
    <label {...props} className={styles.item({ class: className })}>
      <Radio.Root
        value={value}
        disabled={disabled}
        readOnly={readOnly}
        inputRef={inputRef}
        className={styles.radio()}
      >
        <Radio.Indicator className={styles.indicator()} />
      </Radio.Root>
      {children}
    </label>
  );
}

/** A set of mutually exclusive options. Label the group with `aria-labelledby` or a `Fieldset`. */
export const RadioGroup = Object.assign(RadioGroupRoot, {
  Item: RadioGroupItem,
});
